'use strict';
(async()=>{const el=document.getElementById('updateStatus');try{const r=await fetch('update-status.json');if(!r.ok)throw Error();const d=await r.json();const local=new Date(d.checkedAt).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'});const strong=document.createElement('b');strong.textContent='資料の自動更新';const p=document.createElement('p');p.className='small';p.textContent='最終確認：'+local+'（日本時間） ／ '+(d.errors?.length?'一部の取得先でエラー。既存データを維持。':d.needsAction?.length?'新年度の全国資料を検知。取込対応待ち。':'対応資料の確認・検証を完了。')+' 毎週火曜6:17に確認。対象は文京区一般会計、全国2024年度統計、2025年度の全国財政指標・大阪41／福岡60団体の決算速報です。契約先・受取先・交付金事業は個別確認。';const a=document.createElement('a');a.href='update-status.json';a.textContent='対象資料と取得結果（JSON）';a.target='_blank';a.rel='noopener';el.replaceChildren(strong,p,a)}catch{el.textContent='資料の自動更新：確認結果を取得できませんでした。GitHub Actionsの実行履歴をご確認ください。'}})();
